DROP PROCEDURE IF EXISTS shop.fill_audit;
DROP TABLE IF EXISTS shop.audit_log;
DROP TABLE IF EXISTS shop.audit_archive;

CREATE TABLE shop.audit_archive (id BIGINT AUTO_INCREMENT PRIMARY KEY, payload CHAR(255) NOT NULL) DATA DIRECTORY = '/var/lib/dbshoot-audit';
CREATE TABLE shop.audit_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, payload CHAR(255) NOT NULL) DATA DIRECTORY = '/var/lib/dbshoot-audit';
INSERT INTO shop.audit_archive (payload) SELECT REPEAT('a', 255) FROM shop.orders LIMIT {{archive}};

DELIMITER //
CREATE PROCEDURE shop.fill_audit(target BIGINT) SQL SECURITY INVOKER
BEGIN
  WHILE (SELECT COALESCE(SUM(FILE_SIZE), 0) FROM information_schema.INNODB_TABLESPACES WHERE NAME LIKE 'shop/audit%') < target DO
    INSERT INTO shop.audit_log (payload) SELECT REPEAT('b', 255) FROM shop.orders LIMIT 500;
  END WHILE;
END//
DELIMITER ;
CALL shop.fill_audit(32800000);
